    /** @return array<string, mixed> */ public function integrationCapabilities(): array { return ['auth'=>['strategy'=>'api_token','legacy_auth_type'=>'api_token','credential_mode'=>'secret','setup_flows'=>['manual_secret'],'requires_browser_for_setup'=>false,'refreshable'=>false,'token_keys'=>[],'notes'=>['Set the workspace or account host URL and send the Databricks token as Authorization: Bearer.']],'host_availability'=>['web'=>['setup_supported'=>true,'runtime_supported'=>true,'setup_mode'=>'manual_secret'],'cli'=>['setup_supported'=>true,'runtime_supported'=>true,'setup_mode'=>'manual_secret','runtime_mode'=>'normal']],'runtime_requirements'=>[],'compatibility'=>['web_setup_supported'=>true,'web_runtime_supported'=>true,'cli_setup_supported'=>true,'cli_runtime_supported'=>true]]; }
    public function appName(): string { return 'databricks'; } public function appMeta(): array { return ['label'=>'Databricks','description'=>'Lakehouse jobs, SQL warehouses, Unity Catalog, ML, serving, workspace, account, and governance APIs','icon'=>'ph:brackets-curly','logo'=>'ph:brackets-curly']; }
    public function integrationMeta(): array { return ['name'=>'Databricks','description'=>'Manage Databricks workspace and account APIs including jobs, clusters, Unity Catalog, SQL, model serving, MLflow, apps, permissions, billing, and settings.','icon'=>'ph:brackets-curly','logo'=>'ph:brackets-curly','category'=>'data','badge'=>'verified','docs_url'=>'https://docs.databricks.com/aws/en/reference/api']; }
    public function configSchema(): array { return [['key'=>'api_token','type'=>'secret','label'=>'API Token','required'=>true],['key'=>'url','type'=>'url','label'=>'Workspace or Account URL','placeholder'=>'https://dbc-00000000-0000.cloud.databricks.com','required'=>true],['key'=>'account_id','type'=>'text','label'=>'Account ID','required'=>false],['key'=>'workspace_id','type'=>'text','label'=>'Workspace ID','required'=>false]]; }
    /** @param  array<string, mixed>  $config  Credential and endpoint settings. @return array{success: bool, message?: string, error?: string} */ public function testConnection(array $config): array { $token=(string)($config['api_token']??''); $baseUrl=rtrim((string)($config['url']??''),'/'); if($token===''||$baseUrl==='')return ['success'=>false,'error'=>'Databricks host URL and API token are required.']; try{$response=Http::withHeaders(['Authorization'=>'Bearer '.$token,'Accept'=>'application/json'])->timeout(10)->get($baseUrl.'/api/2.0/preview/scim/v2/Me'); if(!$response->successful())return ['success'=>false,'error'=>'Databricks API returned HTTP '.$response->status().'.']; return ['success'=>true,'message'=>'Connected to Databricks at '.$baseUrl.'.'];}catch(\Throwable $e){return ['success'=>false,'error'=>$e->getMessage()];} }
    public function validationRules(): array { return ['api_token'=>'required|string','url'=>'required|url','account_id'=>'nullable|string','workspace_id'=>'nullable|string']; } public function credentialFields(): array { return [['key'=>'api_token','type'=>'secret','label'=>'API Token','required'=>true],['key'=>'url','type'=>'url','label'=>'Workspace or Account URL','required'=>true],['key'=>'account_id','type'=>'text','label'=>'Account ID','required'=>false],['key'=>'workspace_id','type'=>'text','label'=>'Workspace ID','required'=>false]]; }
